{"code": "import os

# Check if KaggleDatasets can access the data
try:
    from kaggle_datasets import KaggleDatasets
    GCS_DS_PATH = KaggleDatasets().get_gcs_path('tpu-getting-started')
    print(f"Kaggle GCS path: {GCS_DS_PATH}")

    # List what's in the GCS path
    import tensorflow as tf
    files = tf.io.gfile.glob(GCS_DS_PATH + '/tfrecords-jpeg-192x192/*/*')
    print(f"Number of files found: {len(files)}")
    if files:
        print("First few files:")
        for f in files[:5]:
            print(f"  {f}")
except Exception as e:
    print(f"Error accessing KaggleDatasets: {type(e).__name__}: {e}")"}

